drop policy if exists shipment_events_staff_select on public.shipment_events; drop policy if exists shipment_events_staff_insert on public.shipment_events; drop policy if exists shipment_events_staff_update on public.shipment_events; create policy shipment_events_staff_select on public.shipment_events for select to authenticated using (exists (select 1 from public.staff s where s.id = auth.uid() and s.is_active = true)); create policy shipment_events_staff_insert on public.shipment_events for insert to authenticated with check (exists (select 1 from public.staff s where s.id = auth.uid() and s.is_active = true)); create policy shipment_events_staff_update on public.shipment_events for update to authenticated using (exists (select 1 from public.staff s where s.id = auth.uid() and s.is_active = true)) with check (exists (select 1 from public.staff s where s.id = auth.uid() and s.is_active = true));;
